CREATE CACHED TABLE PUBLIC.METABASE_FIELD(
    ID INT DEFAULT (NEXT VALUE FOR PUBLIC.SYSTEM_SEQUENCE_FA47720B_962C_473D_8841_5794EBD7CFCE) NOT NULL NULL_TO_DEFAULT SEQUENCE PUBLIC.SYSTEM_SEQUENCE_FA47720B_962C_473D_8841_5794EBD7CFCE SELECTIVITY 100,
    CREATED_AT TIMESTAMP NOT NULL SELECTIVITY 55,
    UPDATED_AT TIMESTAMP NOT NULL SELECTIVITY 98,
    NAME VARCHAR(254) NOT NULL SELECTIVITY 71,
    BASE_TYPE VARCHAR(255) NOT NULL SELECTIVITY 9,
    SEMANTIC_TYPE VARCHAR(255) SELECTIVITY 19,
    ACTIVE BOOLEAN DEFAULT TRUE NOT NULL SELECTIVITY 1,
    DESCRIPTION CLOB,
    PREVIEW_DISPLAY BOOLEAN DEFAULT TRUE NOT NULL SELECTIVITY 1,
    POSITION INT DEFAULT 0 NOT NULL SELECTIVITY 17,
    TABLE_ID INT NOT NULL SELECTIVITY 10,
    PARENT_ID INT SELECTIVITY 1,
    DISPLAY_NAME VARCHAR(254) SELECTIVITY 67,
    VISIBILITY_TYPE VARCHAR(32) DEFAULT 'normal' NOT NULL SELECTIVITY 1,
    FK_TARGET_FIELD_ID INT SELECTIVITY 3,
    LAST_ANALYZED TIMESTAMP SELECTIVITY 5,
    POINTS_OF_INTEREST CLOB,
    CAVEATS CLOB,
    FINGERPRINT CLOB COMMENT 'Serialized JSON containing non-identifying information about this Field, such as min, max, and percent JSON. Used for classification.',
    FINGERPRINT_VERSION INT DEFAULT '0' NOT NULL SELECTIVITY 1 COMMENT 'The version of the fingerprint for this Field. Used so we can keep track of which Fields need to be analyzed again when new things are added to fingerprints.',
    DATABASE_TYPE CLOB NOT NULL,
    HAS_FIELD_VALUES CLOB COMMENT 'Whether we have FieldValues ("list"), should ad-hoc search ("search"), disable entirely ("none"), or infer dynamically (null)"',
    SETTINGS CLOB COMMENT 'Serialized JSON FE-specific settings like formatting, etc. Scope of what is stored here may increase in future.',
    DATABASE_POSITION INT DEFAULT 0 NOT NULL SELECTIVITY 18,
    CUSTOM_POSITION INT DEFAULT 0 NOT NULL SELECTIVITY 1,
    EFFECTIVE_TYPE VARCHAR(255) SELECTIVITY 9 COMMENT 'The effective type of the field after any coercions.',
    COERCION_STRATEGY VARCHAR(255) SELECTIVITY 1 COMMENT 'A strategy to coerce the base_type into the effective_type.',
    NFC_PATH VARCHAR(254) SELECTIVITY 1 COMMENT 'Nested field column paths, flattened',
    DATABASE_REQUIRED BOOLEAN DEFAULT FALSE NOT NULL SELECTIVITY 1 COMMENT 'Indicates this field is required by the database for new records. Usually not null and without a default.'
);         
